def GetTrueLiupai(liupai, iClass):
    if liupai == 1006:
        if iClass == 1:
            liupai = 1012
        elif iClass == 2:
            liupai = 1013
        
    
    if liupai == 2006:
        if iClass == 1:
            liupai = 2012
        elif iClass == 2:
            liupai = 2013
        
    
    if liupai == 1014:
        liupai = 1012
    
    return liupai


def GetHeroInfo(liupai, iClass, key = None):
    liupai = GetTrueLiupai(liupai, iClass)
    if liupai not in HeroData:
        return None
    
    if key is None:
        return HeroData.get(liupai)
    
    return HeroData.get(liupai).get(key, { })


def GetPetInfo(idx):
    return PetsData.get(idx)


def GetLiupaiList(mode):
    return ID2LIUPAI.get(mode, [])

